const factory=[makePreset('Clean Room'),makePreset('Edge of Breakup',{overdrive:{drive:20,level:-12},reverb:{mix:12},eq:{mid:2,high:-1}}),makePreset('Glass Chorus',{chorus:{rate:.7,depth:3.5,mix:34},reverb:{mix:24},eq:{high:2}}),makePreset('Ambient Trail',{chorus:{rate:.3,depth:4,mix:30},delay:{time:600,feedback:55,mix:35},reverb:{decay:5,mix:40}}),makePreset('Slapback',{delay:{time:110,feedback:12,mix:25},overdrive:{drive:12,level:-10},reverb:{mix:8}})];
