try{saved=JSON.parse(localStorage.getItem('signal-presets-v1')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(p=>{try{validatePreset(p);validateIO(p);return typeof p.name==='string';}catch{return false;}});}catch{saved=[];}
function notify(s,error=false){$('#notice').textContent=s;$('#notice').classList.toggle('error',error);}
function dirty(){$('#engine-detail').textContent=ctx?`${model.name||'Custom tone'} · modified`:'Controls are ready. Start audio to hear your sound.';}
function storage(){return new Promise((resolve,reject)=>{if(db)return resolve(db);const r=indexedDB.open('signal-audio-assets',1);r.onupgradeneeded=()=>r.result.createObjectStore('irs');r.onerror=()=>reject(new Error('IR storage is unavailable.'));r.onsuccess=()=>{db=r.result;resolve(db);};});}
