function animate(now=0){if(!ctx)return;requestAnimationFrame(animate);if(now-frameTime<40)return;frameTime=now;meter(inMeter,'input');meter(outMeter,'output');if(now-lastPitch<140)return;lastPitch=now;const p=detectPitch(inSamples,ctx.sampleRate);if(!p){$('#tuner-note').textContent='—';$('#tuner-octave').textContent='';$('#tuner-cents').textContent='Play one string';$('#tuner-hz').textContent='A4 = 440 Hz · pre-effects';$('#needle').style.opacity='0';return;}const n=noteFromFrequency(p.frequency);$('#tuner-note').textContent=n.name;$('#tuner-octave').textContent=n.octave;$('#tuner-cents').textContent=Math.abs(n.cents)<3?'In tune':`${n.cents>0?'+':''}${n.cents.toFixed(0)} cents`;$('#tuner-hz').textContent=`${p.frequency.toFixed(1)} Hz · ${Math.round(p.confidence*100)}% confidence`;$('#needle').style.opacity=1;$('#needle').style.left=`${50+Math.max(-50,Math.min(50,n.cents))}%`;}
function validateIO(p){if(!p.io)p.io={input:0,output:-12};if(typeof p.io.input!=='number'||!Number.isFinite(p.io.input)||p.io.input< -24||p.io.input>24||typeof p.io.output!=='number'||!Number.isFinite(p.io.output)||p.io.output< -60||p.io.output>0)throw new Error('Invalid input/output levels.');}
async function selectPreset(p){validatePreset(p);p=clone(p);validateIO(p);model=p;board?.applyPreset(model);await restoreIR();applyGains();render();$('#engine-detail').textContent=`${model.name||'Imported tone'} · ${ctx?'ready to play':'start audio to listen'}`;}
async function loadIR(file){if(!file)return;await guarded(async()=>{if(file.size>5*1024*1024)throw new Error('Choose an IR smaller than 5 MB.');await ensureAudio();const data=await file.arrayBuffer(),id=crypto.randomUUID();await board.effects.cabinet.loadIR(data,{name:file.name,id});model.effects.cabinet.irId=id;model.effects.cabinet.irName=file.name;let stored=true;try{await irStore(id,{name:file.name,data});}catch{stored=false;}dirty();render();notify(stored?`Loaded ${file.name}. Save a preset to keep this selection.`:'IR loaded for this session, but browser storage failed. Re-upload after reloading.',!stored);});}
async function guarded(task){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');try{await task();}catch(e){const errors={NotAllowedError:'Microphone permission denied. Allow audio input in browser site settings, then reconnect.',NotFoundError:'No audio input found. Connect an interface and try again.',NotReadableError:'Audio input busy or unavailable. Close other apps using it and try again.'};notify(errors[e.name]||e.message,true);}finally{busy=false;document.body.removeAttribute('aria-busy');}}
$('#start').onclick=()=>guarded(ensureAudio);$('#connect').onclick=()=>guarded(connectGuitar);$('#riff').onclick=()=>guarded(playRiff);$('#stop').onclick=stopSource;$('#refresh').onclick=()=>guarded(refreshDevices);$('#channel').onchange=routeInput;
for(const[id,key]of[['input-gain','input'],['output-gain','output']])$('#'+id).oninput=e=>{model.io[key]=Number(e.target.value);$(`#${key}-value`).textContent=`${model.io[key]} dB`;applyGains();dirty();};$('#tuner-mute').onchange=applyGains;$('#bypass').onclick=()=>{bypassed=!bypassed;board?.setBypassed(bypassed);$('#bypass').setAttribute('aria-pressed',bypassed);$('#bypass').textContent=bypassed?'Bypass active':'Bypass all';};
$('#presets').onchange=e=>guarded(async()=>{selected=e.target.value;const[g,i]=selected.split(':');await selectPreset((g==='factory'?factory:saved)[Number(i)]);updateOptions();});$('#reset').onclick=()=>guarded(async()=>{selected='factory:0';await selectPreset(factory[0]);updateOptions();notify('Clean Room restored.');});
function persist(next){localStorage.setItem('signal-presets-v1',JSON.stringify(next));saved=next;}
$('#save').onclick=()=>guarded(async()=>{const name=$('#preset-name').value.trim();if(!name)throw new Error('Give your sound a name first.');const p=clone(model);p.name=name;const i=saved.findIndex(x=>x.name===name),next=clone(saved);if(i>=0)next[i]=p;else next.push(p);persist(next);selected=`saved:${i>=0?i:saved.length-1}`;model.name=name;updateOptions();$('#preset-name').value='';$('#engine-detail').textContent=`${name} · saved`;notify(`Saved “${name}” in this browser.${i>=0?' Existing preset updated.':''}`);});$('#delete').onclick=()=>guarded(async()=>{if(!selected.startsWith('saved:'))return;const i=Number(selected.split(':')[1]),name=saved[i].name;persist(saved.filter((_,n)=>n!==i));selected='factory:0';await selectPreset(factory[0]);updateOptions();notify(`Deleted “${name}”.`);});
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function toBase64(buffer){const b=new Uint8Array(buffer);let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s);}
