$('#export').onclick=()=>guarded(async()=>{const p=clone(model);p.name=$('#preset-name').value.trim()||p.name||'My tone';const id=p.effects.cabinet.irId;if(id){const a=await irStore(id);if(!a)throw new Error('Custom IR missing. Re-upload it before exporting.');p.cabinetAsset={name:a.name,base64:toBase64(a.data)};}download(p,(p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'tone')+'.json');notify('Preset exported. Selected custom cabinet audio is included.');});
$('#import').onclick=()=>$('#preset-file').click();$('#preset-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!file)return;guarded(async()=>{if(file.size>8*1024*1024)throw new Error('Preset file exceeds 8 MB.');const p=JSON.parse(await file.text());validatePreset(p);validateIO(p);if(typeof p.name!=='string'||p.name.length>100)p.name='Imported tone';if(p.cabinetAsset){if(typeof p.cabinetAsset.base64!=='string'||typeof p.cabinetAsset.name!=='string')throw new Error('Invalid embedded IR.');await ensureAudio();const data=fromBase64(p.cabinetAsset.base64),id=crypto.randomUUID();await board.effects.cabinet.loadIR(data,{name:p.cabinetAsset.name,id});await irStore(id,{name:p.cabinetAsset.name,data});p.effects.cabinet.irId=id;p.effects.cabinet.irName=p.cabinetAsset.name;delete p.cabinetAsset;}await selectPreset(p);$('#preset-name').value=p.name;notify(`Imported “${p.name}”. Click Save preset to keep it.`);});};
